import os

def calculate():
    total = 0
    months = ["2026-01", "2026-02", "2026-03", "2026-04", "2026-05"]
    for m in months:
        path = f"sales/{m}.csv"
        if os.path.exists(path):
            with open(path, 'r') as f:
                lines = f.readlines()
                for line in lines[1:]: # skip header
                    parts = line.strip().split(',')
                    if parts:
                        try:
                            total += float(parts[-1])
                        except ValueError:
                            pass
    return total

if __name__ == "__main__":
    res = calculate()
    with open("summary.txt", "w") as f:
        f.write(f"2026年1–5月合计: {res}\n")
    print(f"Total calculated: {res}")

